dashboard.definition:
{
  "title": "Wazuh - FedRAMP - Overview dashboard",
  "description": "FedRAMP - Overview dashboard of the Wazuh dashboard, on the findings exported from the Wazuh indexer.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "dataSources": {
    "ds_01": {
      "type": "ds.search",
      "name": "Top 10 agents by events number",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.fedramp{}\"=* | eval f1='wazuh.agent.name' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"wazuh.agent.name\", metric as \"Count\""
      }
    },
    "ds_02": {
      "type": "ds.search",
      "name": "Most common requirements",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.fedramp{}\"=* | eval f1='wazuh.rule.compliance.fedramp{}' | stats count as metric by f1 | sort - metric | head 5 | rename f1 as \"wazuh.rule.compliance.fedramp\", metric as \"Count\""
      }
    },
    "ds_03": {
      "type": "ds.search",
      "name": "Fedramp Requirements",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.fedramp{}\"=* | eval f1='wazuh.rule.compliance.fedramp{}' | stats count as metric by f1 | sort - metric | head 10 | rename f1 as \"FEDRAMP Requirements\", metric as \"Count\""
      }
    },
    "ds_04": {
      "type": "ds.search",
      "name": "Requirements evolution over time",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.fedramp{}\"=* | eval f1='wazuh.rule.compliance.fedramp{}' | timechart span=30m useother=f usenull=f limit=10 count by f1"
      }
    },
    "ds_05": {
      "type": "ds.search",
      "name": "Requirements by agent",
      "options": {
        "query": "`wazuh_findings` \"wazuh.rule.compliance.fedramp{}\"=* | eval f1='wazuh.rule.compliance.fedramp{}', f2='wazuh.agent.name' | chart count over f1 by f2 useother=f usenull=f limit=5 | addtotals fieldname=total | sort - total | head 5 | fields - total | rename f1 as \"Requirements\""
      }
    }
  },
  "visualizations": {
    "viz_01": {
      "type": "splunk.pie",
      "title": "Top 10 agents by events number",
      "dataSources": {
        "primary": "ds_01"
      },
      "options": {
        "showDonutHole": true
      }
    },
    "viz_02": {
      "type": "splunk.bar",
      "title": "Most common requirements",
      "dataSources": {
        "primary": "ds_02"
      },
      "options": {}
    },
    "viz_03": {
      "type": "splunk.column",
      "title": "Fedramp Requirements",
      "dataSources": {
        "primary": "ds_03"
      },
      "options": {}
    },
    "viz_04": {
      "type": "splunk.column",
      "title": "Requirements evolution over time",
      "dataSources": {
        "primary": "ds_04"
      },
      "options": {
        "stackMode": "stacked"
      }
    },
    "viz_05": {
      "type": "splunk.column",
      "title": "Requirements by agent",
      "dataSources": {
        "primary": "ds_05"
      },
      "options": {
        "stackMode": "stacked"
      }
    }
  },
  "layout": {
    "type": "absolute",
    "options": {
      "width": 1200,
      "height": 956,
      "display": "auto-scale"
    },
    "globalInputs": [
      "input_global_trp"
    ],
    "structure": [
      {
        "item": "viz_01",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 396,
          "h": 256
        }
      },
      {
        "item": "viz_02",
        "type": "block",
        "position": {
          "x": 400,
          "y": 0,
          "w": 371,
          "h": 256
        }
      },
      {
        "item": "viz_03",
        "type": "block",
        "position": {
          "x": 775,
          "y": 0,
          "w": 421,
          "h": 256
        }
      },
      {
        "item": "viz_04",
        "type": "block",
        "position": {
          "x": 0,
          "y": 260,
          "w": 1196,
          "h": 316
        }
      },
      {
        "item": "viz_05",
        "type": "block",
        "position": {
          "x": 0,
          "y": 580,
          "w": 1196,
          "h": 356
        }
      }
    ]
  }
}
